-- Stage 2 of 2: the clean, conformed rows the marts consume.

-- Source systems replay batches, so the same business key can
-- arrive more than once. Keep the most recently ingested version.
with deduplicated as (
    select
        *,
        row_number() over (partition by delivery_event_id order by ingested_at desc nulls last) as _row_rank
    from {{ ref('cln_fact_delivery_events') }}
    where _dq_is_valid
)

select
    delivery_event_id,
    event_ts,
    date_key,
    delivery_id,
    event_type,
    vehicle_id,
    latitude,
    longitude,
    speed_kph,
    odometer_km,
    geofence_name,
    is_exception,
    source_system_code,
    ingested_at,
    _cleansed_at
from deduplicated
where _row_rank = 1
